"""Additive immutable publication ledger; explicit execution only, no seed."""
from alembic import op
revision='d13_0001'
down_revision='d12_0001'
branch_labels=None
depends_on=None

DDL = ('CREATE TABLE published_schedule_versions (\n\tid UUID NOT NULL, \n\tschedule_key VARCHAR(64) NOT NULL, \n\tsequence INTEGER NOT NULL, \n\trevision VARCHAR(64) NOT NULL, \n\tprevious_id UUID, \n\tcontent_json TEXT NOT NULL, \n\tcontent_digest VARCHAR(64) NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tCONSTRAINT uq_published_sequence UNIQUE (schedule_key, sequence), \n\tCONSTRAINT uq_published_revision UNIQUE (schedule_key, revision), \n\tCONSTRAINT ck_published_sequence CHECK (sequence > 0), \n\tFOREIGN KEY(previous_id) REFERENCES published_schedule_versions (id) ON DELETE RESTRICT\n)', 'CREATE TABLE published_schedule_heads (\n\tschedule_key VARCHAR(64) NOT NULL, \n\tversion_id UUID NOT NULL, \n\tsequence INTEGER NOT NULL, \n\tPRIMARY KEY (schedule_key), \n\tUNIQUE (version_id), \n\tFOREIGN KEY(version_id) REFERENCES published_schedule_versions (id) ON DELETE RESTRICT\n)', 'CREATE TABLE schedule_adjustment_applications (\n\tid UUID NOT NULL, \n\trequest_id UUID NOT NULL, \n\tdecision_id UUID NOT NULL, \n\tactor_id UUID NOT NULL, \n\tdepartment_id UUID NOT NULL, \n\toperation_id UUID NOT NULL, \n\tprevious_version_id UUID NOT NULL, \n\tnew_version_id UUID NOT NULL, \n\tcommand_digest VARCHAR(64) NOT NULL, \n\tpayload_json TEXT NOT NULL, \n\tpayload_digest VARCHAR(64) NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tCONSTRAINT uq_application_request UNIQUE (request_id), \n\tCONSTRAINT uq_application_decision UNIQUE (decision_id), \n\tCONSTRAINT uq_application_publication UNIQUE (new_version_id), \n\tCONSTRAINT uq_application_operation UNIQUE (actor_id, operation_id), \n\tFOREIGN KEY(request_id) REFERENCES faculty_adjustment_requests (id) ON DELETE RESTRICT, \n\tFOREIGN KEY(decision_id) REFERENCES faculty_adjustment_decisions (id) ON DELETE RESTRICT, \n\tFOREIGN KEY(actor_id) REFERENCES users (id) ON DELETE RESTRICT, \n\tFOREIGN KEY(previous_version_id) REFERENCES published_schedule_versions (id) ON DELETE RESTRICT, \n\tFOREIGN KEY(new_version_id) REFERENCES published_schedule_versions (id) ON DELETE RESTRICT\n)', "CREATE FUNCTION d13_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'immutable publication history'; END $$", 'CREATE TRIGGER d13_published_schedule_versions_immutable BEFORE UPDATE OR DELETE ON published_schedule_versions FOR EACH ROW EXECUTE FUNCTION d13_immutable()', 'CREATE TRIGGER d13_schedule_adjustment_applications_immutable BEFORE UPDATE OR DELETE ON schedule_adjustment_applications FOR EACH ROW EXECUTE FUNCTION d13_immutable()', 'CREATE TRIGGER d13_head_delete BEFORE DELETE ON published_schedule_heads FOR EACH ROW EXECUTE FUNCTION d13_immutable()', "CREATE FUNCTION d13_version_insert() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NOT ((NEW.sequence=1 AND NEW.previous_id IS NULL) OR EXISTS(SELECT 1 FROM published_schedule_versions p WHERE p.id=NEW.previous_id AND p.schedule_key=NEW.schedule_key AND p.sequence=NEW.sequence-1)) THEN RAISE EXCEPTION 'invalid publication lineage'; END IF; RETURN NEW; END $$", 'CREATE TRIGGER d13_version_insert BEFORE INSERT ON published_schedule_versions FOR EACH ROW EXECUTE FUNCTION d13_version_insert()', "CREATE FUNCTION d13_head_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='INSERT' THEN IF NOT EXISTS(SELECT 1 FROM published_schedule_versions v WHERE v.id=NEW.version_id AND v.schedule_key=NEW.schedule_key AND v.sequence=1 AND NEW.sequence=1) THEN RAISE EXCEPTION 'invalid initial head'; END IF; ELSE IF NEW.schedule_key<>OLD.schedule_key OR NEW.sequence<>OLD.sequence+1 OR NOT EXISTS(SELECT 1 FROM published_schedule_versions v JOIN schedule_adjustment_applications a ON a.new_version_id=v.id WHERE v.id=NEW.version_id AND v.previous_id=OLD.version_id AND v.schedule_key=NEW.schedule_key AND v.sequence=NEW.sequence) THEN RAISE EXCEPTION 'invalid publication transition'; END IF; END IF; RETURN NEW; END $$", 'CREATE TRIGGER d13_head_guard BEFORE INSERT OR UPDATE ON published_schedule_heads FOR EACH ROW EXECUTE FUNCTION d13_head_guard()', "CREATE FUNCTION d13_application_insert() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM faculty_adjustment_requests r JOIN faculty_adjustment_decisions d ON d.request_id=r.id JOIN users u ON u.id=NEW.actor_id JOIN published_schedule_versions p ON p.id=NEW.previous_version_id JOIN published_schedule_versions n ON n.id=NEW.new_version_id WHERE r.id=NEW.request_id AND r.status='SUBMITTED' AND d.id=NEW.decision_id AND d.action='APPROVE' AND d.department_id=NEW.department_id AND u.is_active AND n.previous_id=p.id AND n.schedule_key=p.schedule_key AND n.sequence=p.sequence+1) THEN RAISE EXCEPTION 'invalid application'; END IF; RETURN NEW; END $$", 'CREATE TRIGGER d13_application_insert BEFORE INSERT ON schedule_adjustment_applications FOR EACH ROW EXECUTE FUNCTION d13_application_insert()')

def upgrade():
    for statement in DDL:op.execute(statement)

def downgrade():
    op.execute("DO $$ BEGIN IF EXISTS(SELECT 1 FROM published_schedule_versions) OR EXISTS(SELECT 1 FROM published_schedule_heads) OR EXISTS(SELECT 1 FROM schedule_adjustment_applications) THEN RAISE EXCEPTION 'D13 downgrade refuses retained publication history'; END IF; END $$")
    op.execute('DROP TABLE schedule_adjustment_applications')
    op.execute('DROP TABLE published_schedule_heads')
    op.execute('DROP TABLE published_schedule_versions')
    op.execute('DROP FUNCTION d13_application_insert()')
    op.execute('DROP FUNCTION d13_head_guard()')
    op.execute('DROP FUNCTION d13_version_insert()')
    op.execute('DROP FUNCTION d13_immutable()')
